//! Level 2: the Solana Trenches. Not a battlefield: the memecoin casino of Crypto
//! Twitter, where a coin launches every minute and most of them rug. The casino pays in
//! gold coins, not diamonds; the penguin cashier changes them after the fight. See
//! `level.rs` for the map legend.
//!
//! An explorable map in four storeys, a screen tall each (the camera keeps to the one
//! the wassie is in):
//!
//! - rows 0-19, the top of SAM's tower: the exchange suites (columns 196-247) and his
//!   rooftop arena under the open sky (columns 250-279);
//! - rows 20-43, the neon strip (columns 0-71) and the casino floor (72-211), with the
//!   elevator up to the tower in its lobby (column 206);
//! - rows 44-63, the underground casino: a back room of slot banks and crypto ATMs
//!   (columns 86-190), reached down a hole in the casino floor (164-169), with the
//!   VIP vault behind a false wall (177-190);
//! - rows 64-83, the sewers (columns 4-203): a long corridor full of bots, reached down
//!   the drain at the back room's west end (88-91) or the manhole on the strip (46-48).
//!
//! SAM cut the elevator's power: its breaker (`E`) is at the sewers' east end. Thrown,
//! it lights the elevator, and the shaft beside it (columns 196-202) climbs back up on
//! girders to a hatch in the lobby floor, which only opens from below. The three plasma
//! cells are below ground: in the VIP vault, at the sewers' west end past two fences,
//! and on a pipe in the middle of the sewers, up on the jetpack.

use crate::{
    level::{Area, BossKind, Level, Markers, Theme},
    talk::{Line, Speaker},
};

/// CL207 rings as the wassie walks onto the strip.
static CALL: [Line; 11] = [
    Line { speaker: Speaker::Cl207, rows: &["WASSIE? CL207 HERE.", "CAN YOU HEAR ME?"] },
    Line { speaker: Speaker::Cl207, rows: &["DID YOU MAKE IT ACROSS", "THE BADLANDS IN ONE", "PIECE?"] },
    Line { speaker: Speaker::Wassie, rows: &["BERA 3000 IS SCRAP.", "MY BAGS ARE SAFE."] },
    Line { speaker: Speaker::Cl207, rows: &["GOOD. NOW YOU'RE IN", "THE SOLANA TRENCHES."] },
    Line { speaker: Speaker::Cl207, rows: &["A NEW COIN LAUNCHES", "EVERY MINUTE HERE.", "MOST OF THEM RUG."] },
    Line { speaker: Speaker::Cl207, rows: &["SAM RUNS THIS CASINO", "FROM HIS ROOFTOP. HE", "CUT HIS LIFT'S POWER."] },
    Line { speaker: Speaker::Cl207, rows: &["THE BREAKER IS IN THE", "SEWERS, UNDER THE", "BACK ROOM."] },
    Line { speaker: Speaker::Cl207, rows: &["AND I'M BUILDING A", "PLASMA SHIELD. ITS", "THREE CELLS ARE DOWN"] },
    Line { speaker: Speaker::Cl207, rows: &["THERE TOO. BRING THEM", "BACK UP IF YOU CAN."] },
    Line { speaker: Speaker::Wassie, rows: &["I'LL FIND THEM."] },
    Line { speaker: Speaker::Wassie, rows: &["THE HOUSE NEVER MET", "A DIAMOND HAND."] },
];

/// SAM and the wassie, up on his rooftop.
static TALK: [Line; 8] = [
    Line { speaker: Speaker::Sam, rows: &["OH HEY. WELCOME TO MY", "ROOFTOP. VIP ONLY."] },
    Line { speaker: Speaker::Wassie, rows: &["WHERE ARE EVERYONE'S", "COINS, SAM?"] },
    Line { speaker: Speaker::Sam, rows: &["SAFE. TOTALLY SAFE.", "100 PERCENT BACKED."] },
    Line { speaker: Speaker::Sam, rows: &["BY VIBES, MOSTLY."] },
    Line { speaker: Speaker::Wassie, rows: &["..."] },
    Line { speaker: Speaker::Sam, rows: &["WITHDRAWALS ARE", "PAUSED. FOREVER."] },
    Line { speaker: Speaker::Sam, rows: &["BUT I DO HAVE A", "CUCUMBER FOR YOU!"] },
    Line { speaker: Speaker::Wassie, rows: &["DIAMOND HANDS DON'T", "GET RUGGED."] },
];

